using System.Text.Json;
using System.Security.Cryptography;
using Microsoft.Data.Sqlite;
var repo=Path.GetFullPath(args[0]);var backup=Path.GetFullPath(args[1]);var root=Path.GetFullPath(args[2]);
if(Directory.Exists(root))throw new Exception("Use a fresh isolated fixture directory.");
foreach(var folder in new[]{"data","state","intake-documents","documents"})foreach(var path in Directory.EnumerateFiles(Path.Combine(backup,folder),"*",SearchOption.AllDirectories)){
 var dest=Path.Combine(root,Path.GetRelativePath(backup,path));Directory.CreateDirectory(Path.GetDirectoryName(dest)!);File.Copy(path,dest);
}
var protectedFiles=Directory.GetFiles(root,"*",SearchOption.AllDirectories).Where(p=>!p.Contains("dle-os-sim.db")).ToDictionary(p=>p,p=>Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(p))));
var state=new SimStateStore(root);await state.InitializeAsync();var runtime=state.Current.Metadata!;
var ops=new SimOperationsDataStore(repo,root);await ops.InitializeAsync(runtime);var intakes=new SimRfqIntakeStore(root);
var provider=new SimKittingRequirementsProvider(intakes,ops);var documents=new SimIntakeDocuments(root);
var service=new SimProductionService(state,ops,intakes,provider,documents);
var actor=new SimPersona("quality-test","test","Quality Test Author","ACTIVE",[],[],true,"isolated");
var json=SimProductionService.Json;int count=0;
JsonElement E(object v)=>JsonSerializer.SerializeToElement(v,json);
void Check(bool value,string label){if(!value)throw new Exception(label);count++;Console.WriteLine("PASS "+label);}
async Task Block(Func<Task> run,string label){try{await run();}catch(Exception e)when(e is KittingCaseProblem or SimRfqIntakeProblem or SimOrderEntryPermissionException){Check(true,label);return;}throw new Exception("Not blocked: "+label);}
var wo="0999997";
await Block(async()=>{await provider.ResolveAsync(wo,runtime);},"shop requirements blocked while held");
await Block(async()=>{await new SimKittingCases(state,ops,provider).Start(wo,new(),actor);},"Kitting Start denied");
await Block(async()=>{await service.Read(wo,actor);},"shop production denied");
var initial=E(await service.ReadJobInstructions(wo,actor,true));
Check(initial.GetProperty("version").GetInt32()==0,"held Quality read returns baseline without seeding");
Check(initial.GetProperty("operations").GetArrayLength()==20,"20 accepted operations retained");
var sources=E(await service.ReadInstructionSources(wo,actor,true));
Check(sources.GetProperty("process").GetProperty("canEdit").GetBoolean()==false,"accepted BOM read only");
Check(sources.GetProperty("process").GetProperty("rows").GetArrayLength()==7,"seven BOM rows retained");
var order=E(await intakes.ReadOrderEntry("RFQI-SIM-0046"));
await File.WriteAllTextAsync(Path.Combine(root,"order.json"),order.GetRawText());
await File.WriteAllTextAsync(Path.Combine(root,"sources.json"),sources.GetRawText());
await File.WriteAllTextAsync(Path.Combine(root,"initial.json"),initial.GetRawText());
var operations=initial.GetProperty("operations").Deserialize<SimLaborOperation[]>(json)!;
var token=initial.GetProperty("baselineToken").GetString()!;
var drawing=operations.SelectMany(o=>o.Slides??[]).First(c=>c.Kind=="DRAWING");
var info=await service.ReadInstructionPage(wo,drawing.Source!.DocumentId,drawing.Source.Sha256,0,512,actor,true);
Check(JsonDocument.Parse(info).RootElement.GetProperty("pageCount").GetInt32()>0,"frozen drawing is readable");
await File.WriteAllBytesAsync(Path.Combine(root,"drawing.png"),await service.ReadInstructionPage(wo,drawing.Source.DocumentId,drawing.Source.Sha256,1,800,actor,true));
await File.WriteAllBytesAsync(Path.Combine(root,"drawing-info.json"),info);
await Block(async()=>{await service.ReadInstructionPage(wo,drawing.Source.DocumentId,"wrong",1,800,actor,true);},"different drawing hash denied");
operations[0]=operations[0] with{Instructions="Isolated Quality instruction edit"};
var target=Array.FindIndex(operations,o=>o.Slides?.Any(c=>c.Id==drawing.Id)==true);
var png=Convert.FromBase64String("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aJawAAAAASUVORK5CYII=");
var asset=await service.UploadInstructionAsset(wo,token,"isolated.png",png,actor,true);
Check((await service.OpenInstructionAsset(wo,asset.DocumentId,actor,true)).Bytes.SequenceEqual(png),"WO-scoped image retained exactly");
var added=drawing with{Id=Guid.NewGuid().ToString(),Title="Quality fixture drawing",Stages=[drawing.Stages[0] with{Id=Guid.NewGuid().ToString(),Marks=[new SimDrawingMark(Guid.NewGuid().ToString(),drawing.Page,"text",[new(.3,.3)],"Isolated annotation")],Photos=[new SimLaborSlidePhoto(Guid.NewGuid().ToString(),asset.DocumentId,asset.Sha256,"isolated.png",.1,.1,.2,.2,0)]}]};
var cards=operations[target].Slides!.ToList();cards.Insert(cards.Count-1,added);operations[target]=operations[target] with{Slides=cards.ToArray()};
var saved=E(await service.SaveJobInstructions(wo,new(0,token,operations),actor,true));
Check(saved.GetProperty("version").GetInt32()==1,"Quality saves version 1");
service=new SimProductionService(state,ops,intakes,provider,documents);
var reopened=E(await service.ReadJobInstructions(wo,actor,true));
Check(reopened.GetProperty("operations")[0].GetProperty("instructions").GetString()=="Isolated Quality instruction edit","new service reopens saved content");
Check(reopened.GetProperty("updatedBy").GetString()==actor.DisplayName&&reopened.GetProperty("updatedAt").ValueKind==JsonValueKind.String,"saved author and date retained");
var store=new SimProductionStore(ops.DatabasePath);
Check((await store.ReadInstructions(wo,runtime.Generation))!.Version==1,"shared WO store owns Quality version");
Check((await store.ReadInstructions(wo,runtime.Generation))!.Operations[target].Slides!.Any(c=>c.Id==added.Id&&c.Stages[0].Photos!.Single().DocumentId==asset.DocumentId),"added drawing, marks, stage and image references survive reopen");
var reader=actor with{IsSuperAdmin=false,Permissions=["production.view","order_entry.view"]};
Check(!E(await service.ReadJobInstructions(wo,reader,true)).GetProperty("canEdit").GetBoolean(),"authorized reader sees noneditable Quality packet");
await Block(async()=>{await service.SaveJobInstructions(wo,new(1,token,operations),reader,true);},"read-only Quality user cannot save");
await Block(async()=>{await service.ReadJobInstructions(wo,actor with{IsSuperAdmin=false,Permissions=["production.view","production.manage"]},true);},"production permission alone cannot enter held Quality packet");
await Block(async()=>{await service.SaveJobInstructions(wo,new(0,token,operations),actor,true);},"stale concurrent save denied");
await Block(async()=>{await service.SaveJobInstructions(wo,new(1,"wrong",operations),actor,true);},"wrong baseline denied");
var changed=operations.ToArray();changed[0]=changed[0] with{Name="Changed routing"};
await Block(async()=>{await service.SaveJobInstructions(wo,new(1,token,changed),actor,true);},"operation routing changes denied");
operations[0]=operations[0] with{Instructions="Isolated Quality version two"};
await service.SaveJobInstructions(wo,new(1,token,operations),actor,true);
var v1=E(await service.ReadJobInstructions(wo,actor,true,1));
Check(!v1.GetProperty("canEdit").GetBoolean()&&v1.GetProperty("operations")[0].GetProperty("instructions").GetString()=="Isolated Quality instruction edit","exact version 1 remains immutable after version 2");
Check(v1.GetProperty("reference").GetProperty("contentHash").GetString()==reopened.GetProperty("reference").GetProperty("contentHash").GetString(),"exact-version content reference stable");
await Block(async()=>{await service.ReadJobInstructions(wo,actor,true,99);},"missing version does not fall back to latest");
await Block(async()=>{await service.ReadJobInstructions("0999998",actor,true);},"unqualified WO cannot use Quality authoring");
await Block(async()=>{await service.ReadJobInstructions(wo,actor with{IsSuperAdmin=false},true);},"unauthorized persona denied");
await Block(async()=>{await service.Read(wo,actor);},"instruction saves do not release shop production");
await Block(async()=>{await new SimKittingCases(state,ops,provider).Start(wo,new(),actor);},"instruction saves do not permit Kitting Start");
Check(protectedFiles.All(kv=>Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(kv.Key)))==kv.Value),"all intake, source-document and metadata files unchanged");
Check((await store.Read(wo,runtime.Generation)).Bound is null,"no execution traveler bound");
await File.WriteAllTextAsync(Path.Combine(root,"saved.json"),reopened.GetRawText());
Console.WriteLine($"PASS {count} checks; isolated fixture {root}");
